import { DatePipe } from '@angular/common';
import { Component, input } from '@angular/core';
import { Veranstaltung } from '../../models/veranstaltung';
import { spielstaettenOffset } from '../../utils/zeitzone';

@Component({
  selector: 'app-event-card',
  imports: [DatePipe],
  templateUrl: './event-card.html',
  styleUrl: './event-card.scss'
})
export class EventCard {
  readonly veranstaltung = input.required<Veranstaltung>();

  protected readonly spielstaettenOffset = spielstaettenOffset;
}
<article class="event-card">
  <h3 class="event-card__titel">{{ veranstaltung().titel }}</h3>
  <p class="event-card__meta">
    {{ veranstaltung().spielstaetteName }} ·
    {{ veranstaltung().zeitpunkt | date: 'EEEE, d. MMMM y, HH:mm':spielstaettenOffset(veranstaltung().zeitpunkt) }} Uhr
  </p>
</article>

