    public void Tagesende_Winterzeitdatum_ErgibtLetzteSekundeMitPlusEinerStunde()
    {
        var ergebnis = EuropaBerlinZeitzone.Tagesende(new DateOnly(2026, 1, 15));

        Assert.Equal(TimeSpan.FromHours(1), ergebnis.Offset);
    }
}

