            {
                Id = "E-nach-bereich",
                Titel = "Nach dem Bereich",
                Beschreibung = "-",
                RaumId = "R1",
                DauerMinuten = 60,
                Altersfreigabe = 0,
                Zeitpunkt = new DateTimeOffset(2026, 10, 1, 20, 0, 0, TimeSpan.FromHours(2))
            });
        await _db.SaveChangesAsync();
    }

