1	<main class="programmuebersicht">
2	  <h1 class="programmuebersicht__titel">Programm</h1>
3	
4	  @if (ladezustand() === 'laedt') {
5	    <div class="programmuebersicht__liste" aria-busy="true" aria-label="Veranstaltungen werden geladen">
6	      @for (platzhalter of skeletonPlatzhalter; track platzhalter) {
7	        <div class="event-card-skeleton">
8	          <div class="event-card-skeleton__titel"></div>
9	          <div class="event-card-skeleton__meta"></div>
10	        </div>
11	      }
12	    </div>
13	  } @else if (ladezustand() === 'fehler') {
14	    <p class="programmuebersicht__fehler" role="alert">
15	      Veranstaltungen konnten nicht geladen werden. Bitte versuchen Sie es später erneut.
16	    </p>
17	  } @else if (veranstaltungen().length === 0) {
18	    <p class="programmuebersicht__leerzustand">Aktuell sind keine Veranstaltungen verfügbar.</p>
19	  } @else {
20	    <div class="programmuebersicht__liste">
21	      @for (veranstaltung of veranstaltungen(); track veranstaltung.id) {
22	        <app-event-card [veranstaltung]="veranstaltung" />
23	      }
24	    </div>
25	  }
26	</main>
