    expect(fixture.nativeElement.textContent).toContain('Kammerkonzert Frühling');
    expect(fixture.nativeElement.textContent).toContain('Stadthalle Nordpark');
    expect(fixture.nativeElement.textContent).toContain('19:30');
  });

